use super::*;
use crate::executor::json::{
    JsonBounds, JsonCodecCharge, assert_layout_covers_decode, json_from_slice_bounded,
};
use proptest::prelude::*;
use std::{collections::BTreeMap, marker::PhantomData};

#[derive(serde::Serialize, serde::Deserialize, crate::HeapLayout)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
enum Observation {
    Item { item: WireItem },
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(32))]
    #[test]
    fn bounded_item_reopen_preserves_wire_bytes_and_original_admission(text in ".{0,160}") {
        // Generated byte-preservation inputs, not captured provider transcripts.
        let wire = format!(
            "{{ \"$serde_json::private::RawValue\" : {}, \"extension\" : [1, true] }}",
            serde_json::to_string(&text).unwrap()
        );
        let original = WireItem::capture(
            Provenance {
                family: Family::Responses,
                provider: "original-service".into(),
                model: "original-model".into(),
                endpoint: "https://example.invalid/v1".into(),
            },
            ItemKind::Message,
            RawValue::from_string(wire.clone()).unwrap(),
            [Family::Anthropic, Family::Chat, Family::Gemini].into_iter().map(|family| {
                (family, RawValue::from_string(wire.clone()).unwrap())
            }).collect::<BTreeMap<_, _>>(),
        ).unwrap();
        assert_layout_covers_decode(&original);
        // The same codec must work beneath the journal's tagged observations,
        // where serde buffers fields before choosing a variant.
        assert_layout_covers_decode(&Observation::Item { item: original.clone() });
        let encoded = serde_json::to_vec(&original).unwrap();
        let bounds = JsonBounds {
            maximum_bytes: encoded.len() as u64,
            maximum_items: u64::MAX,
            maximum_depth: 128,
        };
        let mut admissions = 0;
        let reopened = json_from_slice_bounded(
            PhantomData::<WireItem>, &encoded, bounds, None, None, &mut |charge| {
                if matches!(charge, JsonCodecCharge::Admission { .. }) { admissions += 1; }
                Ok(())
            },
        ).unwrap();
        prop_assert_eq!(admissions, 1);
        for family in [Family::Responses, Family::Anthropic, Family::Chat, Family::Gemini] {
            let selected = acyclic_model_render::seg(family, "original-service", &reopened).unwrap().unwrap();
            prop_assert_eq!(selected.get(), wire.as_str());
        }
        // The original admission refusal stops before construction; it cannot
        // fall through to an uncredited decoder or publish a partial value.
        let mut refused = 0;
        let result = json_from_slice_bounded(
            PhantomData::<WireItem>, &encoded, bounds, None, None, &mut |charge| {
                if matches!(charge, JsonCodecCharge::Admission { .. }) {
                    refused += 1;
                    return Err(crate::Error::Cancelled);
                }
                Ok(())
            },
        );
        prop_assert!(matches!(result, Err(crate::Error::Cancelled)));
        prop_assert_eq!(refused, 1);
        let normalized = wire.replace(" : ", ":");
        prop_assert_ne!(normalized, reopened.wire().get());
    }
}

#[cfg(all(feature = "filesystem", not(target_arch = "wasm32")))]
#[tokio::test]
async fn immutable_wire_item_uses_original_journal_load_and_releases_custody() -> crate::Result<()>
{
    let storage =
        crate::filesystem::MemoryHarnessStorage::new(crate::AgentId::new(), 65_536).await?;
    let journal = storage.journal();
    let raw = r#"{ "extension" : {"$serde_json::private::RawValue":"opaque\\bytes"} }"#;
    let item = WireItem::capture(
        Provenance {
            family: Family::Responses,
            provider: "original-service".into(),
            model: "original-model".into(),
            endpoint: "https://example.invalid/v1".into(),
        },
        ItemKind::Reasoning,
        RawValue::from_string(raw.into()).unwrap(),
        BTreeMap::new(),
    )
    .unwrap();
    let cancellation = acyclic_fs::CancellationToken::new();
    let io = crate::executor::PreparationIo::from_budget(
        acyclic_fs::performance::work_budget(1_000_000, 1_000_000),
        &cancellation,
    )?;
    let intent = crate::OperationId::new();
    let provenance = item.provenance().clone();
    let envelope = crate::conversation::envelope::Envelope::new(
        intent,
        [7; 32],
        crate::conversation::envelope::Payload::Wire { item },
        &io,
    )?;
    let encoded = envelope.encode(&io, 65_536)?;
    let changed_version =
        std::str::from_utf8(&encoded)
            .unwrap()
            .replacen("\"version\":1", "\"version\":2", 1);
    assert!(
        crate::conversation::envelope::Envelope::decode(changed_version.as_bytes(), &io).is_err()
    );
    for position in [0, 1] {
        let source = crate::conversation::envelope::SourcePosition::from_record(
            &acyclic_stream::StreamPath::new("context/changes")?,
            position,
            [3; 32],
            &io,
        );
        assert_eq!(source.is_ok(), position == 1);
    }
    // Generated provenance DTOs exercise the original decoder; they are not
    // evidence of filesystem authorization or publication completion.
    let provider = crate::resources::ProviderRef::new(
        "test".into(),
        "filesystem".into(),
        "1".into(),
        &mut None,
    )?;
    let source = crate::context::PinnedContextPath {
        generation: crate::resources::GenerationRef::new(&provider, &[1], None, None)?.0,
        root: crate::context::ContextRoot {
            volume: crate::conversation::VolumeRef::new(
                provider,
                "v".into(),
                crate::conversation::VolumeClass::Project,
                crate::conversation::VolumeOwner::Project("test".into()),
                &mut None,
            )?,
            directory: "skills".into(),
        },
        path: "skills/inspect/SKILL.md".into(),
    };
    let context = crate::conversation::envelope::Envelope::new(
        intent,
        [7; 32],
        crate::conversation::envelope::Payload::Context {
            position: crate::conversation::envelope::SourcePosition::from_record(
                &acyclic_stream::StreamPath::new("context/changes")?,
                1,
                [3; 32],
                &io,
            )?,
            change: crate::conversation::envelope::ContextChange::Removed {
                source: source.clone(),
            },
        },
        &io,
    )?;
    let context_bytes = context.encode(&io, 65_536)?;
    let (restored, restored_hold) =
        crate::conversation::envelope::Envelope::decode(&context_bytes, &io)?;
    let crate::conversation::envelope::Payload::Context {
        change: crate::conversation::envelope::ContextChange::Removed { source: retained },
        ..
    } = restored.payload()
    else {
        panic!("context envelope")
    };
    assert_eq!(retained, &source);
    drop(restored);
    drop(restored_hold);
    let outside_root = std::str::from_utf8(&context_bytes)
        .unwrap()
        .replace("skills/inspect/SKILL.md", "other/inspect/SKILL.md");
    assert!(crate::conversation::envelope::Envelope::decode(outside_root.as_bytes(), &io).is_err());
    // The actual generic journal entry point must not bypass the invariant.
    let mut invalid: serde_json::Value = serde_json::from_str(&outside_root).unwrap();
    invalid.sort_all_objects();
    let invalid = serde_json::to_vec(&invalid).unwrap();
    assert!(
        crate::executor::decode_json::<crate::conversation::envelope::Envelope>(
            &invalid,
            Some(&io),
        )
        .is_err()
    );
    assert!(
        crate::executor::decode_json::<crate::conversation::envelope::Envelope>(&invalid, None,)
            .is_err()
    );
    let reference = crate::executor::stage_json(
        journal.as_ref(),
        intent,
        "original-item",
        &envelope,
        Some(&io),
    )
    .await?;
    for native in [false, true] {
        let cancellation = acyclic_fs::CancellationToken::new();
        let budget = acyclic_fs::performance::work_budget(1_000_000, 1_000_000);
        let work = acyclic_fs::NativeMaterializationWork::new(budget, &cancellation)
            .map_err(|(cause, work)| crate::Error::NativeConstruction { cause, work })?;
        let baseline = work.live_allocation_bytes();
        let io = if native {
            crate::executor::PreparationIo::from_native_work(&work)?
        } else {
            crate::executor::PreparationIo::from_budget(budget, &cancellation)?
        };
        let (loaded, hold) = crate::executor::load_json::<crate::conversation::envelope::Envelope>(
            journal.as_ref(),
            &reference,
            Some(&io),
        )
        .await?;
        assert_eq!(loaded.intent(), intent);
        assert_eq!(loaded.profile(), [7; 32]);
        let crate::conversation::envelope::Payload::Wire { item } = loaded.payload() else {
            panic!("wire envelope")
        };
        assert_eq!(item.wire().get(), raw);
        assert_eq!(item.provenance(), &provenance);
        assert!(
            acyclic_model_render::seg(Family::Chat, "original-service", item)
                .unwrap()
                .is_none()
        );
        drop(loaded);
        drop(hold);
        drop(io);
        assert_eq!(work.live_allocation_bytes(), baseline);
    }
    Ok(())
}
